# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BİR PEYGAMBER TANIYORUM: HZ. İBRAHİM (AS) VE TEVHİD MÜCADELESİ</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Akıl Yürütme ve Tevhid</text>\n  <text x="125" y="100" text-anchor="middle" font-size="11.5" fill="#78350f">• Babil halkı putlara, yıldızlara,</text>\n  <text x="125" y="120" text-anchor="middle" font-size="11.5" fill="#78350f">Ay\'a ve Güneş\'e tapıyordu.</text>\n  <text x="125" y="146" text-anchor="middle" font-size="11.5" fill="#78350f">• Hz. İbrahim batan ve kaybolan</text>\n  <text x="125" y="166" text-anchor="middle" font-size="11.5" fill="#78350f">varlıkların ilah olamayacağını</text>\n  <text x="125" y="186" text-anchor="middle" font-size="11.5" fill="#78350f">sorgulayarak Tevhid\'i savundu.</text>\n  <text x="125" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Unvanı: Halîlullah (Allah\'ın dostu)</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fdf2f8" stroke="#db2777" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Ateş İmtihanı ve Mucize</text>\n  <text x="350" y="100" text-anchor="middle" font-size="11.5" fill="#831843">• Putların kendilerini bile</text>\n  <text x="350" y="120" text-anchor="middle" font-size="11.5" fill="#831843">koruyamadığını halka gösterdi.</text>\n  <text x="350" y="146" text-anchor="middle" font-size="11.5" fill="#831843">• Kral Nemrut tarafından ateşe</text>\n  <text x="350" y="166" text-anchor="middle" font-size="11.5" fill="#831843">atıldı; Allah\'ın emriyle ateş</text>\n  <text x="350" y="186" text-anchor="middle" font-size="11.5" fill="#831843">serin ve selametli oldu.</text>\n  <text x="350" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">Enbiyâ Suresi, 69. Ayet</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Kâbe\'nin İnşası ve Dua</text>\n  <text x="575" y="100" text-anchor="middle" font-size="11.5" fill="#14532d">• Oğlu Hz. İsmail (as) ile birlikte</text>\n  <text x="575" y="120" text-anchor="middle" font-size="11.5" fill="#14532d">Mekke\'de Kâbe\'yi inşa etti.</text>\n  <text x="575" y="146" text-anchor="middle" font-size="11.5" fill="#14532d">• Müslümanların kıblesi olan</text>\n  <text x="575" y="166" text-anchor="middle" font-size="11.5" fill="#14532d">Beytullah\'ı yükseltti.</text>\n  <text x="575" y="186" text-anchor="middle" font-size="11.5" fill="#14532d">• Neslinin namaz kılanlardan</text>\n  <text x="575" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">olması için Rabbena duası yaptı.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HZ. İBRAHİM\'İN (AS) KUR\'AN\'DAKİ NAMAZ VE BAĞIŞLANMA DUASI</text>\n  <rect x="25" y="48" width="650" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="350" y="76" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">İbrahim Suresi, 40 ve 41. Ayetler (Namazda Okunan Rabbena Duaları)</text>\n  <text x="350" y="110" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e3a8a">1. «Rabbic\'alnî mukîme\'s-salâti ve min zürriyyetî Rabbenâ ve tekabbel duâ\'»</text>\n  <text x="350" y="134" text-anchor="middle" font-size="11.5" fill="#1e293b">Anlamı: «Ey Rabbim! Beni ve soyumdan gelecekleri namazı dosdoğru kılanlardan eyle; Rabbimiz, duamı kabul buyur!»</text>\n  <text x="350" y="168" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e3a8a">2. «Rabbenağfirlî ve li-vâlideyye ve li\'l-mü\'minîne yevme yekûmu\'l-hisâb»</text>\n  <text x="350" y="192" text-anchor="middle" font-size="11.5" fill="#1e293b">Anlamı: «Rabbimiz! Hesap görülecek günde beni, anne babamı ve bütün müminleri bağışla!»</text>\n  <text x="350" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Namazların son oturuşunda (ka\'de-i âhire) Tahiyyat ve Salli-Barik dualarından sonra okunur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">2. ÜNİTE BÜTÜNCÜL ÖZETİ: NAMAZ İBADETİ VE ÖNEMİ</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Hazırlık Şartları (Dış Farzlar)</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11.5" fill="#14532d">1. Hadesten Taharet (Abdest/Gusül)</text>\n  <text x="125" y="120" text-anchor="middle" font-size="11.5" fill="#14532d">2. Necasetten Taharet (Temizlik)</text>\n  <text x="125" y="142" text-anchor="middle" font-size="11.5" fill="#14532d">3. Setr-i Avret (Örtünme)</text>\n  <text x="125" y="164" text-anchor="middle" font-size="11.5" fill="#14532d">4. İstikbal-i Kıble (Kâbe\'ye yönelme)</text>\n  <text x="125" y="186" text-anchor="middle" font-size="11.5" fill="#14532d">5. Vakit · 6. Niyet</text>\n  <text x="125" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Namaza başlamadan önce tamamlanır.</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#ecfeff" stroke="#0891b2" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Kılınış Şartları (İç Rükünler)</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11.5" fill="#155e75">1. İftitah (Başlama) Tekbiri</text>\n  <text x="350" y="120" text-anchor="middle" font-size="11.5" fill="#155e75">2. Kıyam (Ayakta durmak)</text>\n  <text x="350" y="142" text-anchor="middle" font-size="11.5" fill="#155e75">3. Kıraat (Kur\'an okumak)</text>\n  <text x="350" y="164" text-anchor="middle" font-size="11.5" fill="#155e75">4. Rükû (Eğilmek)</text>\n  <text x="350" y="186" text-anchor="middle" font-size="11.5" fill="#155e75">5. Secde · 6. Ka\'de-i Âhire (Son oturuş)</text>\n  <text x="350" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">Son oturuşta Tahiyyat duası okunur.</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#f5f3ff" stroke="#7c3aed" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#5b21b6">Namazın Kazandırdıkları</text>\n  <text x="575" y="98" text-anchor="middle" font-size="11.5" fill="#4c1d95">• Allah ile bağ ve manevi huzur</text>\n  <text x="575" y="120" text-anchor="middle" font-size="11.5" fill="#4c1d95">• Beden, elbise ve çevre temizliği</text>\n  <text x="575" y="142" text-anchor="middle" font-size="11.5" fill="#4c1d95">• Zamanı planlama disiplini</text>\n  <text x="575" y="164" text-anchor="middle" font-size="11.5" fill="#4c1d95">• Kötülüklerden uzaklaşma</text>\n  <text x="575" y="186" text-anchor="middle" font-size="11.5" fill="#4c1d95">• Cemaatle birlik ve kardeşlik</text>\n  <text x="575" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#5b21b6">Ankebût Suresi, 45. Ayet</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
